import React, { useEffect, useState } from "react";
import {
  Card,
  CardHeader,
  CardContent,
  CardActions,
  Avatar,
  Typography,
  IconButton,
  Grid,
  Box,
  Button,
  TextField,
  Badge,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  List,
  ListItem,
  ListItemText
} from "@mui/material";
import { Favorite, ChatBubbleOutline } from "@mui/icons-material";

const API = process.env.REACT_APP_API_URL || "http://localhost:5000/api";

export default function Feed() {
  const [posts, setPosts] = useState([]);
  const [text, setText] = useState("");
  const [selectedImage, setSelectedImage] = useState(null);
  const [preview, setPreview] = useState(null);
  const [commentOpenFor, setCommentOpenFor] = useState(null);
  const [commentText, setCommentText] = useState("");

  // get current user from localStorage if logged in
  const storedUser = JSON.parse(localStorage.getItem("user") || "null");
  const userId = storedUser?.id || "guest";
  const username = storedUser?.name || "Anonymous";

  useEffect(() => {
    fetchPosts();
  }, []);

  const fetchPosts = async () => {
    try {
      const res = await fetch(`${API}/posts`);
      if (!res.ok) throw new Error("Fetch posts failed");
      const data = await res.json();
      setPosts(data);
    } catch (err) {
      console.error(err);
    }
  };

  // ✅ Create Post (Text + Image)
  const handleCreate = async () => {
    if (!text.trim() && !selectedImage) {
      alert("Please add text or an image!");
      return;
    }

    const formData = new FormData();
    formData.append("userId", userId);
    formData.append("username", username);
    formData.append("text", text);
    if (selectedImage) formData.append("image", selectedImage);

    try {
      const res = await fetch(`${API}/posts`, {
        method: "POST",
        body: formData,
      });
      if (!res.ok) throw new Error("Create failed");
      const created = await res.json();
      setPosts(prev => [created, ...prev]);
      setText("");
      setSelectedImage(null);
      setPreview(null);
    } catch (err) {
      console.error(err);
      alert("Could not create post");
    }
  };

  // ✅ Like handler
  const toggleLike = async (postId) => {
    setPosts(prev =>
      prev.map(p =>
        p._id === postId
          ? {
              ...p,
              likes: (p.likes || []).includes(userId)
                ? p.likes.filter(u => u !== userId)
                : [...(p.likes || []), userId],
            }
          : p
      )
    );

    try {
      const res = await fetch(`${API}/posts/${postId}/like`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userId }),
      });
      if (!res.ok) throw new Error("Like failed");
      const data = await res.json();
      setPosts(prev =>
        prev.map(p =>
          p._id === postId ? { ...p, likes: data.likes } : p
        )
      );
    } catch (err) {
      console.error(err);
      fetchPosts();
    }
  };

  const openComments = (postId) => {
    setCommentOpenFor(postId);
    setCommentText("");
  };

  const submitComment = async () => {
    if (!commentText.trim()) return;
    const postId = commentOpenFor;

    setPosts(prev =>
      prev.map(p =>
        p._id === postId
          ? {
              ...p,
              comments: [
                ...(p.comments || []),
                { user: username, text: commentText },
              ],
            }
          : p
      )
    );

    setCommentText("");
    setCommentOpenFor(null);

    try {
      const res = await fetch(`${API}/posts/${postId}/comment`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userId, username, text: commentText }),
      });
      if (!res.ok) throw new Error("Comment failed");
      const data = await res.json();
      setPosts(prev =>
        prev.map(p =>
          p._id === postId ? { ...p, comments: data.comments } : p
        )
      );
    } catch (err) {
      console.error(err);
      fetchPosts();
    }
  };

  // ✅ Image preview when user selects image
  const handleImageChange = (e) => {
    const file = e.target.files[0];
    setSelectedImage(file);
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setPreview(reader.result);
      reader.readAsDataURL(file);
    } else {
      setPreview(null);
    }
  };

  return (
    <Box sx={{ mt: 4 }}>
      <Typography variant="h5" sx={{ mb: 2 }}>
        Create a Post
      </Typography>
      <Box sx={{ display: "flex", flexDirection: "column", gap: 2, mb: 4 }}>
        <TextField
          label="What's on your mind?"
          variant="outlined"
          value={text}
          onChange={(e) => setText(e.target.value)}
          fullWidth
        />
        <input type="file" accept="image/*" onChange={handleImageChange} />
        {preview && (
          <Box
            component="img"
            src={preview}
            alt="preview"
            sx={{
              width: "100%",
              maxHeight: 250,
              objectFit: "cover",
              borderRadius: 2,
              boxShadow: 2,
            }}
          />
        )}
        <Button variant="contained" color="primary" onClick={handleCreate}>
          Post
        </Button>
      </Box>

      {/* Feed List */}
      <Grid container spacing={3}>
        {posts.map((p) => (
          <Grid item xs={12} md={6} lg={4} key={p._id}>
            <Card sx={{ boxShadow: 3 }}>
              <CardHeader
                avatar={<Avatar>{(p.username || "A")[0].toUpperCase()}</Avatar>}
                title={p.username}
                subheader={new Date(p.createdAt).toLocaleString()}
              />
              {p.imageUrl && (
                <Box
                  component="img"
                  src={`${API.replace("/api", "")}${p.imageUrl}`}
                  alt="post"
                  sx={{
                    width: "100%",
                    maxHeight: 300,
                    objectFit: "cover",
                  }}
                />
              )}
              <CardContent>
                <Typography>{p.text}</Typography>
              </CardContent>
              <CardActions disableSpacing>
                <IconButton onClick={() => toggleLike(p._id)} aria-label="like">
                  <Badge badgeContent={(p.likes || []).length} color="error">
                    <Favorite
                      color={(p.likes || []).includes(userId) ? "error" : "inherit"}
                    />
                  </Badge>
                </IconButton>
                <IconButton
                  onClick={() => openComments(p._id)}
                  aria-label="comment"
                >
                  <Badge badgeContent={(p.comments || []).length} color="primary">
                    <ChatBubbleOutline />
                  </Badge>
                </IconButton>
              </CardActions>
            </Card>
          </Grid>
        ))}
      </Grid>

      {/* Comment Dialog */}
      <Dialog
        open={!!commentOpenFor}
        onClose={() => setCommentOpenFor(null)}
        fullWidth
      >
        <DialogTitle>Comments</DialogTitle>
        <DialogContent>
          <List sx={{ maxHeight: 300, overflow: "auto" }}>
            {posts.find((x) => x._id === commentOpenFor)?.comments?.map((c, i) => (
              <ListItem key={i} alignItems="flex-start">
                <ListItemText
                  primary={c.user || c.userId || "Anonymous"}
                  secondary={c.text}
                />
              </ListItem>
            )) || <Typography>No comments</Typography>}
          </List>
          <TextField
            value={commentText}
            onChange={(e) => setCommentText(e.target.value)}
            label="Write a comment"
            fullWidth
            multiline
            rows={2}
            sx={{ mt: 2 }}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setCommentOpenFor(null)}>Close</Button>
          <Button variant="contained" onClick={submitComment}>
            Post Comment
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}
